import {uid,expenseScope,planScope,workspaceExpenses,workspacePlans,workspaceSummary,currencies,precision,minor,major,money,allocate,split,expenseFrom,balances,transfers,planProgress,totals,validateTrip,dates,csv,newTrip,sampleTrip} from './core.js';
import {Cloud} from './cloud.js';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',plan:'M8 3v4m8-4v4M4 10h16M5 5h14a1 1 0 0 1 1 1v14H4V6a1 1 0 0 1 1-1Z',money:'M3 7h17v13H3V5l14-2v4m-2 6h6v4h-6Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-5v5l3 2',share:'M12 16V3m-5 5 5-5 5 5M5 12H3v9h18v-9h-2',leaf:'M20 3C8 1 2 10 6 16c6 7 16-1 14-13ZM4 21 16 8',Stay:'M3 19V5m0 10h18v4m0-4V9H8v6m-5-7h5v7',Food:'M5 3v7m4-7v7m-4-4h4m-2 4v11M18 3c-4 4-4 9 0 9v9m0-18v9',Transport:'M6 16h12M4 4h16v12H4Zm2 12-2 5m14-5 2 5M4 10h16M8 13h.01M16 13h.01',Explore:'M12 3 3 8l9 5 9-5-9-5ZM3 12l9 5 9-5M3 16l9 5 9-5',Other:'M12 3v18M3 12h18',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',info:'M12 11v6m0-10h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6Z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18',lock:'M5 10h14v11H5Zm3 0V7a4 4 0 0 1 8 0v3m-4 4v3',undo:'M8 4 3 9l5 5M3 9h10a7 7 0 0 1 0 14',copy:'M8 8h13v13H8ZM3 16V3h13',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M6 6l1 1m10 10 1 1M6 18l1-1M17 7l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',train:'M5 17h14V4H5Zm0-8h14M8 13h.01M16 13h.01M8 17l-3 4m11-4 3 4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.Explore}"/></svg>`;
const initial=()=>({version:1,trips:[sampleTrip()],selected:'sample-vienna',view:'home',day:'',moneyTab:'mine',personViews:{}});
let state;try{state=JSON.parse(localStorage.getItem('roam-state-v1'))||initial();if(state.version!==1||!state.trips.length)state=initial();state.trips.forEach(validateTrip);}catch{state=initial();}
let openingShared=Boolean(new URL(location.href).searchParams.get('trip'));
let cloudTrip=null,cloudStatus='Saved on this device',editRevision=null,search='',undo=null,busy=false,toastTimer;
const cloud=new Cloud(t=>{if(t)cloudTrip=t;else if(!cloud.trip)cloudTrip=null;render();},s=>{cloudStatus=s;render();if(s.includes('needs review')||s==='Access unavailable')toast(s);});
const trip=()=>cloudTrip||state.trips.find(t=>t.id===state.selected)||state.trips[0];
const space=()=>trip().people.some(p=>p.id===state.workspaceViews?.[trip().id])?state.workspaceViews[trip().id]:'group';
const me=()=>space()!=='group'?space():trip().people.find(p=>p.id===state.personViews[trip().id])?.id||cloud.traveler||trip().me;
function chooseSpace(id){state.workspaceViews??={};state.workspaceViews[trip().id]=id;if(id!=='group')state.personViews[trip().id]=id;state.moneyTab=id==='group'?'shared':'personal';search='';persist();render();}
const name=(id,t=trip())=>t.people.find(p=>p.id===id)?.name||'Traveler';
const isPersonalExpense=e=>e&&expenseScope(e)==='personal';
const avatar=(id,t=trip())=>`<span class="avatar" title="${esc(name(id,t))}">${esc(name(id,t).split(' ').slice(0,2).map(n=>n[0]).join('').toUpperCase())}</span>`;
const avatars=(ids,t=trip())=>`<div class="avatars">${ids.slice(0,4).map(id=>avatar(id,t)).join('')}${ids.length>4?`<span>+${ids.length-4}</span>`:''}</div>`;
const fmt=(amount,t=trip())=>money(amount,t.currency);
const date=(s,options={day:'numeric',month:'short'})=>new Intl.DateTimeFormat('en-GB',options).format(new Date(s+'T12:00:00'));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:trip().timezone||undefined,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const currentDay=()=>state.day&&state.day>=trip().start&&state.day<=trip().end?state.day:(today()>=trip().start&&today()<=trip().end?today():trip().start);
const canEdit=()=>!openingShared&&(!cloudTrip||cloud.canEdit);
const button=(label,action,style='secondary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function persist(){try{localStorage.setItem('roam-state-v1',JSON.stringify(state));}catch{throw Error('Device storage is full or unavailable. Export a backup before continuing.');}}
async function mutate(fn,{allowArchive=false,revision=editRevision}={}){
  if(busy)throw Error('Please wait for the current save.');if(!canEdit())throw Error('You have view-only access.');if(trip().archived&&!allowArchive)throw Error('Reopen this archived trip before making changes.');
  const before=structuredClone(trip()),next=structuredClone(before);fn(next);validateTrip(next);busy=true;
  try{if(cloudTrip){try{await cloud.save(next,revision??cloud.revision);}catch(e){try{localStorage.setItem('roam-draft-'+next.id,JSON.stringify({app:'roam-together',version:1,trip:next,savedAt:new Date().toISOString(),reason:e.message}));}catch{}throw e;}cloudTrip=next;cloudStatus='Saved to cloud';}
  else{const prev=state.trips;state.trips=state.trips.map(t=>t.id===next.id?next:t);try{persist();}catch(e){state.trips=prev;throw e;}undo=before;}
  render();}finally{busy=false;}
}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 370 240" fill="none" aria-hidden="true"><circle cx="284" cy="74" r="46" fill="#dae5c9"/><path d="M0 225c77-38 108-4 168-22s114-12 202 8v29H0Z" fill="#d8e2cc"/><path d="M95 211V119h76v92m-83-92h90l-45-31-45 31Zm28-12V77h34v30m-17-29V54m-7 14h14m-32 71h12v22h-12Zm33 0h12v22h-12Zm-31 40h41v32m-22-32v32M190 211V97h89v114m-94-114h100l-50-32-50 32Zm39-27V40h22v30m-11-30V17m-7 12h14m-36 86h12v20h-12Zm34 0h12v20h-12Zm-34 38h12v21h-12Zm34 0h12v21h-12Zm-23 58v-24a11 11 0 0 1 22 0v24M294 212v-70h43v70m-48-70h53l-27-26-26 26Zm14 16h7v14h-7Zm18 0h7v14h-7Zm-17 27h23M72 214V162m-1 21c-28 3-27-30-8-30-12-22 25-28 20-3 24-1 20 36-12 33ZM343 214v-34m-1 10c-20 1-19-25-6-24-8-18 19-22 17-2 18 2 12 28-11 26ZM62 214h291" stroke="#8ba17b" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="m168 48 10-3 10 3m-14 1 4-4 4 4m139 40 9-3 9 3" stroke="#8ba17b" stroke-width="1.5"/><circle cx="133" cy="123" r="5" stroke="#8ba17b" stroke-width="1.5"/></svg>`;}
function budgetAction(style='secondary'){return canEdit()&&!trip().archived&&(!cloudTrip||cloud.canManage)?button(trip().budget?'Edit budget':'Set budget','budget',style):'';}
function workspaceBar(){const t=trip(),personal=space()!=='group';return `<section class="workspace-bar ${personal?'personal-space':''}" aria-label="Trip workspace"><div class="workspace-picker"><label for="workspace-select">${personal?'PERSONAL SPACE':'JOINT TRIP · MASTER'}</label><select id="workspace-select" aria-describedby="workspace-hint"><option value="group" ${!personal?'selected':''}>Joint trip (Master)</option>${t.people.map(p=>`<option value="${esc(p.id)}" ${space()===p.id?'selected':''}>${esc(p.name)} — Personal space</option>`).join('')}</select></div><p id="workspace-hint">${personal?'Your own expenses and group shares. Connected to the shared itinerary.':'Shared itinerary, group plans, and split costs. Add friends at any time.'}${personal?`<br>${button('Edit name','person','ghost',`data-id="${esc(me())}" ${!canEdit()||t.archived||cloudTrip&&!cloud.canManage?'disabled':''}`)}`:''}</p>${button(icon('plus')+' Add friend','person','secondary',!canEdit()||t.archived||cloudTrip&&!cloud.canManage?'disabled':'')}</section>`;}
function statCards(items){return `<div class="stats">${items.map(([label,value,foot])=>`<div class="stat"><div class="stat-top">${esc(label)}</div><div class="stat-value">${esc(value)}</div><div class="stat-foot">${esc(foot)}</div></div>`).join('')}</div>`;}
function personalStats(){const w=workspaceSummary(trip(),me());return statCards([['Personal spending',fmt(w.personalSpent),'Only this traveler’s own purchases'],['My share of joint costs',fmt(w.sharedCost),'Your portion of group expenses'],['My expected total',fmt(w.forecast),'Personal + shared + remaining plans'],[w.net>0?'I should receive':w.net<0?'I need to pay':'My group balance',w.net?fmt(Math.abs(w.net)):'All settled','Personal purchases create no group debt']]);}
function crewSpaces(){const t=trip();return `<section class="card crew-spaces" aria-label="Friends and personal spaces"><div class="section-top"><div><h2>Friends & personal spaces</h2><p>Add someone whenever they join. Existing expense shares stay the same.</p></div>${button(icon('plus')+' Add friend','person','secondary',!canEdit()||t.archived||cloudTrip&&!cloud.canManage?'disabled':'')}</div><div class="crew-grid">${t.people.map(p=>{const w=workspaceSummary(t,p.id);return `<div class="crew-space">${avatar(p.id)}<div><h3>${esc(p.name)}</h3><p>Own expenses ${fmt(w.personalSpent)}<br>Joint cost share ${fmt(w.sharedCost)}</p></div>${button('Open personal space','open-personal','ghost',`data-person="${esc(p.id)}"`)}</div>`;}).join('')}</div></section>`;}
function personalHome(){const t=trip(),d=currentDay();return `<div class="page-heading"><div><div class="eyebrow">CONNECTED TO ${esc(t.name.toUpperCase())}</div><h1>${esc(name(me()))}’s personal space</h1><p>Your purchases, your group shares, and one shared itinerary.</p></div>${button(icon('plus')+' Add personal expense','expense','orange')}</div>${personalStats()}<div class="dashboard-grid"><section><div class="card"><div class="section-top"><div><h2>My personal expenses</h2><p>Individual purchases stay in this traveler’s ledger.</p></div>${button('All my costs','go-money','ghost')}</div>${expenseRows('personal')}</div><div class="card"><div class="section-top"><h2>My upcoming costs</h2>${button('Plan my cost','planned','ghost')}</div>${planCosts()}</div></section><aside><div class="card"><div class="section-top"><div><h2>Shared itinerary</h2><p>${date(d,{weekday:'long',day:'numeric',month:'long'})}</p></div>${button('Full itinerary','go-plan','ghost')}</div>${activityList(d)}<p class="small-muted">These are the master trip’s activities. Personal costs can link to any stop.</p></div>${settlementCard()}</aside></div>`;}

function stats(){if(space()!=='group')return personalStats();const t=trip(),total=totals(t),w=workspaceSummary(t),left=total.budgetLeft;return `<div class="stats"><div class="stat budget-stat"><div class="stat-top">Whole-trip budget ${icon('money')}</div><div class="stat-value">${t.budget?fmt(t.budget):'Not set'}</div><div class="stat-foot">${t.budget?fmt(Math.abs(left))+' '+(left<0?'over budget':'left after all spending'):'Shared and personal spending combined'}</div>${budgetAction('small')}</div>${[['Joint expenses',w.sharedCost,'Shared payments in the master trip'],['Personal expenses',w.personalSpent,'Combined across traveler spaces'],['Whole-trip forecast',total.forecast,'All spending + unpaid plans']].map(([label,value,foot])=>`<div class="stat"><div class="stat-top">${label}</div><div class="stat-value">${fmt(value)}</div><div class="stat-foot">${foot}</div></div>`).join('')}</div>`;}
function quickStart(){if(!canEdit()||trip().archived)return '';return `<section class="quick-start" aria-label="Trip shortcuts"><div class="section-top"><div><h2>What would you like to do?</h2><p>Start with your friends and budget, then build your plans.</p></div></div><div class="quick-grid">${[['1','Add friends','Choose who travels and shares costs.','person'],['2',trip().budget?'Edit budget':'Set budget','Set a spending limit for the whole trip.','budget'],['3','Add activity','Add a place, time, and directions.','activity'],['4','Add joint expense','Record a payment shared by the group.','expense']].filter(x=>x[3]!=='budget'||!cloudTrip||cloud.canManage).map(([n,label,help,action])=>`<button class="quick-step" data-action="${action}"><span class="step-number">${n}</span><span><strong>${label}</strong><small>${help}</small></span>${icon('plus')}</button>`).join('')}</div></section>`;}
function budgetGuide(){const t=trip(),total=totals(t),left=t.budget-total.forecast;return `<section class="card budget-guide" aria-label="Budget planner"><div class="section-top"><div><h2>Plan your budget</h2><p>The whole-trip limit includes joint expenses and everyone’s personal purchases.</p></div>${budgetAction()}</div><div class="budget-breakdown"><div><span>Already spent</span><strong>${fmt(total.spent)}</strong></div><span class="budget-sign">+</span><div><span>Still planned</span><strong>${fmt(total.remaining)}</strong></div><span class="budget-sign">=</span><div><span>Expected total</span><strong>${fmt(total.forecast)}</strong></div></div><p class="budget-outlook">${t.budget?`${fmt(Math.abs(left))} ${left<0?'over your budget if all plans go ahead.':'left in your budget if all plans go ahead.'}`:(!cloudTrip||cloud.canManage?'Set a budget above to see how much you have left.':'The trip owner can set the budget for everyone.')}</p><div class="money-help"><div><strong>Before you pay</strong><p>Add a planned cost to estimate spending and choose who will pay first.</p>${canEdit()&&!t.archived?button('Add planned cost','planned','ghost'):''}</div><div><strong>After you pay</strong><p>Add an expense to record the actual payment and calculate who owes whom.</p>${canEdit()&&!t.archived?button('Add expense','expense','ghost'):''}</div></div></section>`;}

function plannedShare(id){const t=trip();return t.plans.filter(p=>!p.cancelled&&p.participants.includes(id)).reduce((s,p)=>s+(allocate(planProgress(t,p).remaining,Object.fromEntries(p.participants.map(x=>[x,1])))[id]||0),0);}
function activityCard(a,index=0){const t=trip(),plans=workspacePlans(t,space()==='group'?null:me()).filter(p=>p.activityId===a.id&&!p.cancelled),amount=plans.reduce((s,p)=>s+p.amount,0);return `<div class="activity"><div class="time-col">${esc(a.time)}</div><div class="activity-line"><div class="activity-box ${index===0?'featured':''}" role="button" tabindex="0" data-action="activity-detail" data-id="${esc(a.id)}"><div class="activity-title"><span class="category-icon ${esc(a.category)}">${icon(a.category)}</span><h3>${esc(a.title)}</h3>${icon('chevron')}</div><p class="activity-location">${icon('pin')}${esc(a.address||'Add a location')}</p><div class="activity-bottom">${avatars(a.participants)}<span>${amount?`${fmt(amount)} total · ${esc(name(plans[0].payer))} ${name(plans[0].payer)==='You'?'pay':'pays'} upfront`:'No planned cost'}</span></div></div></div></div>`;}
function activityList(day){const activities=trip().activities.filter(a=>a.date===day).sort((a,b)=>a.time.localeCompare(b.time));return activities.length?activities.map(activityCard).join(''):`<div class="empty">${icon('sun')}<h3>A little room for adventure</h3><p>Add your first stop for this day.</p>${button(icon('plus')+' Add activity','activity','secondary')}</div>`;}
function settlementCard(){const t=trip(),b=balances(t)[me()]||balances(t)[t.me],tx=transfers(t);return `<div class="balance-card"><div class="section-top"><h2>All square, made simple</h2>${icon('people')}</div><p class="small-muted">A little less “who owes what?”</p><div class="balance-summary"><div><small>${b.net>0?'You should receive':b.net<0?'You need to pay':'Your balance'}</small><strong>${b.net?fmt(Math.abs(b.net)):'All settled'}</strong></div><div class="round">${icon(b.net?'arrow':'check')}</div></div>${tx.slice(0,3).map(s=>`<div class="settlement-row">${avatar(s.from)}<div class="names">${esc(name(s.from))} ${icon('arrow')} ${esc(name(s.to))}<small>Suggested repayment</small></div><strong>${fmt(s.amount)}</strong></div>`).join('')||'<p class="small-muted">Everyone is settled up. Enjoy the trip.</p>'}${button('See all balances '+icon('arrow'),'go-money','secondary')}</div>`;}
function checklist(limit=0){const t=trip(),tasks=limit?t.tasks.slice(0,limit):t.tasks;return tasks.map(task=>`<div class="checklist-row ${task.done?'done':''}"><label><input type="checkbox" data-task="${esc(task.id)}" ${task.done?'checked':''} ${!canEdit()||t.archived?'disabled':''}><span>${esc(task.title)}</span></label>${task.assignee?avatar(task.assignee):''}${!limit?`<button class="icon-btn" data-action="delete-task" data-id="${esc(task.id)}" aria-label="Delete ${esc(task.title)}">${icon('close')}</button>`:''}</div>`).join('')||'<p class="small-muted">Nothing on the list yet. Add a task below.</p>';}
function home(){if(space()!=='group')return personalHome();const t=trip(),d=currentDay(),dayLabel=d===today()?'Today’s little adventures':'Your first day, all lined up';return `<div class="page-heading"><div><div class="eyebrow">YOUR TRAVEL WORKSPACE</div><h1>The joint trip.</h1><p>One itinerary and group plan. Each friend has a connected personal space.</p></div>${button(icon('plus')+' Add joint expense','expense','orange')}</div><div class="hero"><div class="hero-copy"><div class="eyebrow">${t.sample?'A LITTLE INSPIRATION FOR YOUR NEXT TRIP':'YOUR NEXT CHAPTER'}</div><h1>${esc(t.name)}</h1><p>Your plans, your people, and every little detail. Together in one place.</p><div class="hero-meta"><span>${icon('pin')}${esc(t.destination)}</span><span>${icon('plan')}${date(t.start)} – ${date(t.end,{day:'numeric',month:'short',year:'numeric'})}</span><span>${icon('people')}${t.people.length} traveler${t.people.length===1?'':'s'}</span></div></div><span class="hero-tag">${t.sample?'SAMPLE TRIP':t.archived?'ARCHIVED':'LET’S GO SOMEWHERE'}</span>${heroArt()}</div>${stats()}${quickStart()}${crewSpaces()}<div class="dashboard-grid"><section><div class="section-top"><div><h2>${dayLabel}</h2><p>A plan with plenty of room to wander.</p></div>${button('Full itinerary '+icon('arrow'),'go-plan','ghost')}</div><div class="date-label">${icon('plan')}${date(d,{weekday:'long',day:'numeric',month:'long'})}<span class="tag">DAY ${dates(t.start,t.end).indexOf(d)+1}</span></div>${activityList(d)}${button(icon('plus')+' Add a little adventure','activity','ghost')}</section><aside class="side-column">${settlementCard()}<div class="card"><div class="section-top"><h2>Before you go</h2><span class="pill gray">${t.tasks.filter(x=>x.done).length}/${t.tasks.length}</span></div>${checklist(4)}${button('View checklist '+icon('arrow'),'go-trip','ghost')}</div></aside></div>`;}
function planCosts(activityId){const t=trip(),plans=workspacePlans(t,space()==='group'?null:me()).filter(p=>!activityId||p.activityId===activityId);return plans.map(p=>{const pg=planProgress(t,p);return `<div class="cost-row"><div class="cost-row-head"><strong>${esc(p.title)}</strong><strong>${fmt(p.amount)}</strong></div><p>${planScope(p)==='personal'?'Personal · '+esc(name(p.payer)):esc(name(p.payer))+' pays upfront · '+p.participants.length+' sharing'}${p.due?' · Due '+date(p.due):''}</p><p>${fmt(pg.paid)} paid${space()!=='group'?' · My remaining share '+fmt(allocate(pg.remaining,Object.fromEntries(p.participants.map(id=>[id,1])))[me()]||0):''}${p.cancelled?' · Cancelled':` · ${fmt(pg.remaining)} remaining`}</p><div class="cost-row-actions"><span class="pill ${p.cancelled?'gray':pg.remaining?'orange':''}">${p.cancelled?'Cancelled':pg.remaining?pg.paid?'Partly paid':'Planned':'Paid'}</span>${pg.remaining&&!p.cancelled?button('Record payment','expense','ghost',`data-plan="${esc(p.id)}"`):''}${button('Edit','planned','ghost',`data-id="${esc(p.id)}"`)}</div></div>`;}).join('')||'<p class="small-muted">Add an estimate and choose who will pay upfront.</p>';}
function plan(){const t=trip(),day=currentDay(),activities=t.activities.filter(a=>a.date===day).sort((a,b)=>a.time.localeCompare(b.time));const overlap=activities.some((a,i)=>i&&activities[i-1].endTime>a.time);return `<div class="page-heading"><div><div class="eyebrow">ONE DAY AT A TIME</div><h1>Shared itinerary</h1><p>The master plan for everyone. Link joint or personal costs to these activities.</p></div>${button(icon('plus')+' Add activity','activity','orange')}</div><div class="day-tabs">${dates(t.start,t.end).map((d,i)=>`<button class="day-tab ${d===day?'active':''}" data-action="day" data-day="${d}">Day ${i+1}<strong>${date(d)}</strong></button>`).join('')}</div>${overlap?'<div class="notice">Some activities overlap. Check their start and end times before you head out.</div>':''}<div class="plan-layout"><section><div class="section-top"><h2>${date(day,{weekday:'long',day:'numeric',month:'long'})}</h2><span class="small-muted">${activities.length} stops</span></div>${activityList(day)}</section><aside><div class="card"><div class="section-top"><h2>Plan the payments</h2>${icon('money')}</div><p class="small-muted">Choose who fronts each cost. Debts start when an actual payment is recorded.</p>${planCosts()}${button(icon('plus')+' Add planned cost','planned','ghost')}</div><div class="detail-box"><h3>Know where you’re going</h3><p>Tap an activity for its meeting point, booking details, participants, and directions.</p></div></aside></div>`;}
function expenseRows(sectionOverride){const t=trip(),personal=space()!=='group',section=sectionOverride||(state.moneyTab==='shared'?'shared':'personal');const rows=workspaceExpenses(t,personal?me():null,section).filter(e=>(e.title+' '+e.category+' '+Object.keys(e.payers).map(id=>name(id)).join(' ')).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return rows.length?`<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Paid upfront</th><th class="money-amount">Total</th>${personal&&section==='shared'?'<th>My share</th>':''}<th></th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${date(e.date)} · ${esc(e.category)}${e.kind==='refund'?' · Refund':''}</small></td><td>${avatars(Object.keys(e.payers))}<small>${isPersonalExpense(e)?'Personal · '+esc(name(Object.keys(e.shares)[0])):Object.keys(e.shares).length+' sharing'}</small></td><td class="money-amount">${e.kind==='refund'?'−':''}${fmt(e.baseAmount)}${e.currency!==t.currency?`<small>${money(e.amount,e.currency)}</small>`:''}</td>${personal&&section==='shared'?`<td class="money-amount">${e.kind==='refund'?'−':''}${fmt(e.baseShares[me()]||0)}</td>`:''}<td><button class="icon-btn" data-action="expense-detail" data-id="${esc(e.id)}" aria-label="Details for ${esc(e.title)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>${personal&&section!=='shared'?'No personal expenses yet':'No joint expenses here yet'}</h3><p>${personal&&section!=='shared'?'Add your own purchase here, or open Shared costs to see your group share.':'Add a shared payment in the Joint trip workspace.'}</p></div>`;}
function repaymentList(){const t=trip();return t.settlements.filter(s=>space()==='group'||s.from===me()||s.to===me()).slice().reverse().map(s=>`<div class="cost-row"><div class="cost-row-head"><strong>${esc(name(s.from))} → ${esc(name(s.to))}</strong><strong>${fmt(s.baseAmount)}</strong></div><p>${date(s.date)}${s.note?' · '+esc(s.note):''}</p><div class="cost-row-actions"><span class="pill ${s.reversed?'gray':s.status==='pending'?'orange':''}">${s.reversed?'Reversed':s.status==='pending'?'Sent · awaiting receipt':'Received'}</span>${!s.reversed&&(s.status==='pending'?(!cloudTrip||cloud.canConfirm(s))?button('Confirm received','confirm-settlement','ghost',`data-id="${esc(s.id)}"`):'':(!cloudTrip||cloud.canConfirm(s))?button('Reverse record','reverse-settlement','ghost',`data-id="${esc(s.id)}"`):'')}</div></div>`).join('')||'<p class="small-muted">No repayments recorded yet. Payments happen outside the app.</p>';}
function moneyView(){const t=trip(),personal=space()!=='group',b=balances(t),w=workspaceSummary(t,personal?me():null),tx=transfers(t).filter(x=>!personal||x.from===me()||x.to===me()),tab=(personal?['personal','shared','upcoming']:['shared','upcoming']).includes(state.moneyTab)?state.moneyTab:personal?'personal':'shared',rows=personal&&tab==='shared'?'My share of joint expenses':personal?'My personal expense ledger':'Joint expense ledger';state.moneyTab=tab;return `<div class="page-heading"><div><div class="eyebrow">${personal?'YOUR CONNECTED PERSONAL SPACE':'JOINT TRIP · MASTER'}</div><h1>${personal?esc(name(me()))+'’s costs':'Joint budget & costs'}</h1><p>${personal?'Your own expenses and your share of the group plan.':'Record split expenses here. Each traveler’s own purchases stay in their personal space.'}</p></div>${button(icon('plus')+' '+(personal?'Add personal expense':'Add joint expense'),'expense','orange')}</div>${stats()}${!personal?budgetGuide():`<div class="notice">Personal spending ${fmt(w.personalSpent)} + joint cost share ${fmt(w.sharedCost)} = ${fmt(w.cost)} spent for this traveler. The shared itinerary is available in Itinerary.</div>`}<div class="tabs">${personal?`<button data-action="money-tab" data-tab="personal" class="${tab==='personal'?'active':''}">Personal expenses</button>`:''}<button data-action="money-tab" data-tab="shared" class="${tab==='shared'?'active':''}">${personal?'Shared costs':'Joint expenses'}</button><button data-action="money-tab" data-tab="upcoming" class="${tab==='upcoming'?'active':''}">Planned costs</button></div><div class="money-grid"><section>${tab==='upcoming'?`<div class="card"><div class="section-top"><div><h2>${personal?'My upcoming costs':'Joint payment plans'}</h2><p>${personal?'Includes your personal plans and group plans you take part in.':'Group estimates, participants, and who pays first.'}</p></div>${button(icon('plus')+' Planned cost','planned')}</div>${planCosts()}</div>`:`<div class="card"><div class="section-top"><div><h2>${rows}</h2><p>${personal&&tab==='shared'?'The total payment and your individual share are shown separately.':personal?'These purchases do not add debt between friends.':'Shared payments from the master trip.'}</p></div>${button(icon('download')+' Full-trip CSV','export-csv','ghost')}</div><div class="toolbar"><input class="search" id="expense-search" aria-label="Search expenses" placeholder="Search this ledger…" value="${esc(search)}"><span class="small-muted">${workspaceExpenses(t,personal?me():null,tab).length} records</span></div><div id="expense-table">${expenseRows()}</div></div>`}${!personal?`<div class="card"><h2>Everyone’s share</h2>${t.people.map(p=>{const x=workspaceSummary(t,p.id);return `<div class="person-summary">${avatar(p.id)}<div><p>${esc(p.name)}</p><small>Joint share ${fmt(x.sharedCost)} · Own purchases ${fmt(x.personalSpent)}</small></div>${button('Personal space','open-personal','ghost',`data-person="${esc(p.id)}"`)}</div>`;}).join('')}</div>`:''}</section><aside><div class="balance-card"><div class="section-top"><h2>${personal?'My group repayments':'Who pays whom'}</h2>${icon('arrow')}</div><p class="small-muted">Personal purchases create no group debt. Confirmed repayments update these balances.</p>${tx.map(x=>`<div class="cost-row"><div class="cost-row-head"><strong>${esc(name(x.from))} → ${esc(name(x.to))}</strong><strong>${fmt(x.amount)}</strong></div>${button('Record repayment','repayment','ghost',`data-from="${x.from}" data-to="${x.to}" data-amount="${x.amount}"`)}</div>`).join('')||'<div class="preview">All settled.</div>'}</div><div class="card"><h2>Repayment history</h2>${repaymentList()}</div></aside></div>`;}
function tripView(){const t=trip(),owner=!cloudTrip||cloud.canManage;return `<div class="page-heading"><div><div class="eyebrow">THE LITTLE DETAILS, TAKEN CARE OF</div><h1>Your trip, your people.</h1><p>Bring everyone along. Keep everything together.</p></div>${button(icon('plus')+' New trip','new-trip','orange')}</div><div class="trip-grid"><section><div class="card"><div class="section-top"><h2>The essentials</h2>${button(icon('edit')+' Edit','settings','ghost')}</div><div class="field" style="margin-top:18px"><label for="trip-page-select">Switch adventure</label><select id="trip-page-select">${cloudTrip?`<option value="cloud">${esc(t.name)} · Live</option>`:''}${state.trips.map(x=>`<option value="${x.id}" ${!cloudTrip&&x.id===t.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="details-list"><div class="details-row"><span>Trip</span><strong>${esc(t.name)}</strong></div><div class="details-row"><span>Destination</span><strong>${esc(t.destination)}</strong></div><div class="details-row"><span>Dates</span><strong>${date(t.start)} – ${date(t.end)}</strong></div><div class="details-row"><span>Total trip budget</span><div class="budget-detail"><strong>${t.budget?fmt(t.budget):'Not set'}</strong>${budgetAction('ghost')}</div></div><div class="details-row"><span>Default upfront payer</span><strong>${esc(name(t.defaultPayer))}</strong></div><div class="details-row"><span>Time zone</span><strong>${esc(t.timezone)}</strong></div></div></div><div class="card"><div class="section-top"><h2>The travel crew</h2>${button(icon('plus')+' Add friend','person','ghost')}</div>${t.people.map(p=>`<div class="person-summary">${avatar(p.id)}<div><p>${esc(p.name)}${p.id===me()?' <span class="pill gray">My view</span>':''}</p><small>${p.id===t.defaultPayer?'Default upfront payer':cloud.meta?.accounts?.[p.id]?'Linked account':'Traveler'}</small></div><button class="icon-btn" data-action="person" data-id="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">${icon('edit')}</button></div>`).join('')}${button('Open a personal space','view-person','ghost')}</div><div class="card"><div class="section-top"><h2>Before you go</h2><span class="pill gray">${t.tasks.filter(x=>x.done).length}/${t.tasks.length}</span></div>${checklist()}${button(icon('plus')+' Add task','task','ghost')}</div></section><aside><div class="card"><div class="section-top"><h2>Bring the group together</h2>${icon('share')}</div>${cloudTrip?`<div class="notice green">${cloud.linkAccess?'Anyone with the link can view and edit. No sign-in or approval needed.':'This older trip still uses restricted access.'}</div>${button(icon('share')+' '+(cloud.linkAccess?'Copy trip link':'Enable link sharing'),'share','secondary')}${button('Open another shared trip','open-cloud','ghost')}`:`<p class="small-muted">This trip is currently saved on this device. Save it to the cloud to get a live link for your friends.</p><div class="actions-stack">${button(icon('share')+' Set up live sharing','share','secondary')}${button('Open a shared trip','open-cloud','ghost')}</div>`}</div><div class="card"><div class="section-top"><h2>A copy for the road</h2>${icon('download')}</div><p class="small-muted">Keep a backup before your trip. JSON includes the whole trip; CSV contains expenses.</p><div class="actions-stack">${button(icon('download')+' Download trip backup','export-json','secondary')}${button(icon('download')+' Export expenses (CSV)','export-csv','secondary')}${button(icon('print')+' Print itinerary & budget','print','secondary')}${button(icon('plus')+' Import a trip backup','import','ghost')}${button('Download unsaved draft','export-draft','ghost')}</div></div><div class="card"><h2>Keep things tidy</h2><div class="actions-stack">${!cloudTrip||cloud.role==='owner'?button(t.archived?'Reopen trip':'Archive trip','archive','secondary'):''}${!cloudTrip?button('Undo last change','undo','ghost',!undo?'disabled':''):''}${!cloudTrip&&t.sample?button('Reset sample trip','reset-sample','ghost'):''}${cloud.user?button('Sign out of shared trips','signout','ghost'):''}</div></div></aside></div>`;}
function render(){const t=trip();if(!t)return;const views={home,plan,money:moneyView,trip:tripView};const view=views[state.view]?state.view:'home';const warning=!navigator.onLine||cloudStatus.includes('unavailable');$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="go-home"><img src="./icon.svg" alt=""><span class="brand-word">roam<small>TOGETHER</small></span></a><div class="workspace-label">YOUR ADVENTURES</div><div class="trip-switch"><select id="trip-select" aria-label="Switch trip">${cloudTrip?`<option value="cloud">${esc(t.name)} · Live</option>`:''}${state.trips.map(x=>`<option value="${x.id}" ${!cloudTrip&&x.id===t.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><nav class="nav" aria-label="Main navigation">${[['home','home','Overview'],['plan','plan','Itinerary'],['money','money','Budget & costs'],['trip','people','Trip & friends']].map(([v,i,label])=>`<button data-action="go-${v}" class="${view===v?'active':''}" title="${label}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${view===v?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-card">${icon('leaf')}<h3>Collect moments, not tabs.</h3><p>A little planning.<br>A lot more adventure.</p></div><div class="profile">${avatar(me())}<div><select id="person-select" aria-label="View money as">${t.people.map(p=>`<option value="${p.id}" ${p.id===me()?'selected':''}>${esc(p.name)}</option>`).join('')}</select><small>${cloudTrip?'Shared adventure':'Your travel workspace'}</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="mobile-brand"><img src="./icon.svg" alt="">roam</div><div class="breadcrumb">Your adventures ${icon('chevron')} <span>${esc(t.destination||t.name)}</span></div><div class="top-actions"><div class="sync-badge ${warning?'warning':''}"><span class="sync-dot"></span>${esc(!navigator.onLine?'Offline · device drafts':cloudTrip?cloudStatus:'Saved on this device')}</div>${button(icon('plus')+' New trip','new-trip','')}${button(icon('share')+' Invite friends','share','secondary')}</div></header><main class="content" id="main">${t.archived?'<div class="notice archive-banner">This trip is archived. Reopen it in Trip to make changes.</div>':''}${cloudTrip&&!cloud.canEdit?'<div class="notice">You have view-only access to this trip.</div>':''}${!openingShared?workspaceBar():''}${openingShared?'<div class="empty"><h2>Opening your shared adventure…</h2><p>Loading the latest plans and costs.</p></div>':views[view]()}${t.sample&&!openingShared?`<p class="sample-note">${icon('info')}Sample trip with fictional payments and bookings. ${button('Create your own adventure','new-trip','ghost')}</p>`:''}<footer class="footer"><span>Made for the journey, and the people in it.</span><span>${icon('leaf')} A little more together.</span></footer></main></div>`;}
const input=(label,key,value='',type='text',extra='')=>`<div class="field"><label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const select=(label,key,options,value='')=>`<div class="field"><label for="f-${key}">${label}</label><select id="f-${key}" name="${key}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;
const textarea=(label,key,value='')=>`<div class="field"><label for="f-${key}">${label}</label><textarea id="f-${key}" name="${key}" maxlength="2000">${esc(value)}</textarea></div>`;
const peopleOptions=()=>trip().people.map(p=>[p.id,p.name]);
const chips=(selected=trip().people.map(p=>p.id),key='participants')=>`<span class="field-label">Who shares this?</span><div class="chips">${trip().people.map(p=>`<label class="check-chip"><input type="checkbox" name="${key}" value="${p.id}" ${selected.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div>`;
const error=e=>{const box=$('#form-error');if(box){box.textContent=e.message||String(e);box.scrollIntoView({block:'nearest'});}else toast(e.message||String(e));};
function modal(title,subtitle,body,submit,onSubmit){
  editRevision=cloudTrip?cloud.revision:null;const dlg=$('#modal');dlg.innerHTML=`<form id="dialog-form"><div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button type="button" class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body"><div class="form-error" id="form-error" role="alert"></div>${body}</div><div class="dialog-footer">${button('Close','close','secondary','type="button"')}${submit?`<button class="btn" type="submit">${submit}</button>`:''}</div></form>`;
  $$('button[data-action]',dlg).forEach(b=>{b.type='button';});
  if(!dlg.open)dlg.showModal();
  $('#dialog-form').onsubmit=async ev=>{ev.preventDefault();const b=$('button[type="submit"]',dlg);if(b)b.disabled=true;$('#form-error').textContent='';try{await onSubmit?.(new FormData(ev.currentTarget),ev.currentTarget);if(dlg.open)dlg.close();editRevision=null;}catch(e){error(e);}finally{if(b)b.disabled=false;}};
}
function budgetDialog(){const t=trip();modal(t.budget?'Edit trip budget':'Set your trip budget','How much can the whole group spend on this trip?',`${input('Total budget ('+t.currency+')','budget',t.budget?major(t.budget,t.currency):'','number',`required min="0" step="${10**-precision(t.currency)}" placeholder="e.g. 1200" aria-describedby="budget-help"`)}<p class="small-muted" id="budget-help">${t.people.length===1?'Enter your total for the whole trip.':`Enter one total for all ${t.people.length} travelers.`} For example, if 4 friends each plan to spend 300, enter 1200. This is a planning limit; add actual payments separately as expenses.</p><div class="preview" id="budget-preview" aria-live="polite"></div><p class="small-muted" style="margin-top:12px">Currency: ${esc(t.currency)}. Change it in Trip & friends → Edit before recording any costs. Enter 0 to remove the limit.</p>`,'Save budget',async fd=>{await mutate(next=>{next.budget=minor(fd.get('budget'),t.currency);});toast('Budget saved. Your spending and balances are unchanged.');});const field=$('#f-budget'),preview=$('#budget-preview');const update=()=>{try{const amount=minor(field.value,t.currency),spent=totals(t).spent;preview.textContent=!field.value?'Enter your total above to preview the budget.':!amount?'No spending limit set.':`${money(amount,t.currency)} for the whole trip · about ${money(Math.round(amount/t.people.length),t.currency)} per traveler if shared equally. ${money(Math.abs(amount-spent),t.currency)} ${amount<spent?'over budget already.':'left after recorded expenses.'}`;}catch{preview.textContent='Enter a valid budget amount.';}};field.addEventListener('input',update);update();}
function settingsDialog(isNew=false){const t=trip();const start=isNew?new Date().toISOString().slice(0,10):t.start;modal(isNew?'Start a new adventure':'The trip essentials',isNew?'A few details now. The rest can wait.':'Keep your dates, budget, and payment plan in one place.',`${input('Trip name','name',isNew?'':t.name,'text','required maxlength="120" placeholder="A long weekend in…"')}${input('Destination','destination',isNew?'':t.destination,'text','required maxlength="200" placeholder="City, country"')}<div class="form-grid">${input('Start date','start',start,'date','required')}${input('End date','end',isNew?start:t.end,'date','required')}${select('Trip currency','currency',currencies,isNew?'EUR':t.currency)}${input('Total budget for everyone','budget',isNew?'':major(t.budget,t.currency),'number','min="0" step="any" placeholder="e.g. 1200"')}</div><p class="small-muted budget-hint">Budget = your spending limit for the whole trip, including all travelers. You can skip it now and use Set budget later.</p>${isNew?input('Your name','person','You','text','required maxlength="80"'):select('Who usually pays upfront?','defaultPayer',peopleOptions(),t.defaultPayer)}${input('Time zone','timezone',isNew?Intl.DateTimeFormat().resolvedOptions().timeZone:t.timezone,'text','required placeholder="Europe/Budapest"')}<p class="small-muted">${isNew?'Start solo or add friends afterwards. Everyone’s shares stay linked to each expense.':'Changing the currency is available before you add money records. Planned payments do not create debt.'}</p>`,isNew?'Create trip':'Save changes',async fd=>{
  const obj=Object.fromEntries(fd),days=dates(obj.start,obj.end);if(!days.length||new Date(obj.end)-new Date(obj.start)>59*86400000)throw Error('Choose a trip of up to 60 days, with the end after the start.');try{new Intl.DateTimeFormat('en',{timeZone:obj.timezone});}catch{throw Error('Enter a valid time zone, such as Europe/Budapest.');}
  if(isNew){const nt=newTrip(obj);nt.timezone=obj.timezone;validateTrip(nt);cloud.stop();cloudTrip=null;state.trips.push(nt);state.selected=nt.id;state.view='home';state.day='';persist();render();toast('Your adventure is ready. Add a stop or invite your crew.');}
  else await mutate(next=>{if(obj.currency!==next.currency&&(next.expenses.length||next.plans.length||next.settlements.length))throw Error('Keep the existing currency once money is recorded. Start another trip to use a new base currency.');if(next.activities.some(a=>a.date<obj.start||a.date>obj.end))throw Error('The new dates must still include your itinerary activities.');Object.assign(next,{name:obj.name.trim(),destination:obj.destination.trim(),start:obj.start,end:obj.end,currency:obj.currency,budget:minor(obj.budget||0,obj.currency),defaultPayer:obj.defaultPayer,timezone:obj.timezone});});
});}
function activityDialog(id){const t=trip(),a=t.activities.find(x=>x.id===id);modal(a?'Edit your stop':'Add a little adventure','The where, when, and who — all together.',`${input('Activity name','title',a?.title||'','text','required maxlength="160" placeholder="Coffee, a museum, a beautiful detour…"')}<div class="form-grid">${input('Date','date',a?.date||currentDay(),'date',`required min="${t.start}" max="${t.end}"`)}${select('Category','category',['Explore','Food','Stay','Transport','Other'],a?.category||'Explore')}${input('Start time','time',a?.time||'10:00','time','required')}${input('End time','endTime',a?.endTime||'11:00','time','required')}</div>${input('Place / full address','address',a?.address||'','text','maxlength="500" placeholder="Paste an address for directions"')}${input('Meeting point','meeting',a?.meeting||'','text','maxlength="200" placeholder="Main entrance, platform, café…"')}${chips(a?.participants)}<details class="advanced"><summary>Transport, booking & notes</summary>${select('Getting there','travelMode',['Walk','Public transport','Train','Car','Taxi','Flight','Other'],a?.travelMode||'Walk')}${input('Travel time from previous stop (minutes)','travelMinutes',a?.travelMinutes||'','number','min="0" max="1440"')}${input('Departure / origin','origin',a?.origin||'','text','maxlength="300"')}${input('Booking link','bookingUrl',a?.bookingUrl||'','url','placeholder="https://…"')}${input('Booking reference','reference',a?.reference||'','text','maxlength="100"')}<div class="form-grid">${select('Booked by','bookedBy',peopleOptions(),a?.bookedBy||t.defaultPayer)}${select('Booking status','bookingStatus',['Planned','Reserved','Confirmed','Cancelled'],a?.bookingStatus||'Planned')}</div>${input('Cancellation deadline','cancelBy',a?.cancelBy||'','date')}${textarea('Notes / arrival instructions','notes',a?.notes||'')}</details>`,'Save activity',async fd=>{const obj=Object.fromEntries(fd);if(obj.time>obj.endTime)throw Error('For overnight travel, use separate departure and arrival activities. End time must follow start time.');const participants=fd.getAll('participants');if(!participants.length)throw Error('Choose at least one traveler.');if(obj.date<t.start||obj.date>t.end)throw Error('Choose a date within this trip.');await mutate(next=>{const item={...obj,id:a?.id||uid(),title:obj.title.trim(),participants};next.activities=a?next.activities.map(x=>x.id===a.id?item:x):[...next.activities,item];});toast('Activity saved.');});}
function activityDetail(id){const t=trip(),a=t.activities.find(x=>x.id===id);if(!a)return;const linked=workspaceExpenses(t,space()==='group'?null:me()).filter(e=>e.activityId===id);const location=a.address||t.destination;const map='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(location),dir='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(location)+(a.origin?'&origin='+encodeURIComponent(a.origin):'');modal(esc(a.title),date(a.date,{weekday:'long',day:'numeric',month:'long'})+' · '+a.time+'–'+a.endTime,`<div class="detail-box"><h3>${icon('pin')} ${esc(location)}</h3><p>${esc(a.meeting||'Add a meeting point so everyone knows where to go.')}</p><div style="display:flex;gap:8px;margin-top:14px"><a class="btn secondary small" href="${map}" target="_blank" rel="noopener noreferrer">Open map ${icon('external')}</a><a class="btn small" href="${dir}" target="_blank" rel="noopener noreferrer">Directions ${icon('arrow')}</a></div></div><div class="details-list" style="margin-bottom:20px"><div class="details-row"><span>Getting there</span><strong>${esc(a.travelMode||'Not set')}${a.travelMinutes?' · '+esc(a.travelMinutes)+' min estimate':''}</strong></div><div class="details-row"><span>Who’s joining</span>${avatars(a.participants)}</div><div class="details-row"><span>Booking</span><strong>${esc(a.bookingStatus||'Planned')}${a.reference?' · '+esc(a.reference):''}</strong></div>${a.cancelBy?`<div class="details-row"><span>Cancel by</span><strong>${date(a.cancelBy)}</strong></div>`:''}</div>${a.bookingUrl?`<a class="btn secondary small" href="${esc(a.bookingUrl)}" target="_blank" rel="noopener noreferrer">Open booking ${icon('external')}</a>`:''}${a.notes?`<p class="small-muted" style="white-space:pre-wrap;margin:17px 0">${esc(a.notes)}</p>`:''}<h3>Costs & upfront payments</h3>${planCosts(id)}<p class="small-muted" style="margin-top:12px">${linked.length} payment record${linked.length===1?'':'s'} in this workspace linked to this activity.</p><div class="actions-stack">${button(icon('plus')+' Add planned cost','planned','secondary',`data-activity="${id}"`)}${button(icon('plus')+' Record an expense','expense','secondary',`data-activity="${id}"`)}${button(icon('edit')+' Edit activity','activity','ghost',`data-id="${id}"`)}${button('Delete activity','delete-activity','ghost',`data-id="${id}"`)}</div>`,null);}
function plannedDialog(id,activityId){const t=trip(),p=t.plans.find(x=>x.id===id),a=t.activities.find(x=>x.id===(p?.activityId||activityId)),personal=p?planScope(p)==='personal':space()!=='group';modal(p?'Edit planned cost':'Plan a payment','Link a joint or personal estimate to the shared itinerary.',`${select('Plan type','scope',[['shared','Joint trip — shared cost'],['personal','Personal cost']],personal?'personal':'shared')}${input('What is this cost for?','title',p?.title||a?.title||'','text','required maxlength="160"')}<div class="form-grid">${input('Expected total ('+t.currency+')','amount',p?major(p.amount,t.currency):'','number','required min="0" step="any"')}${input('Pay by','due',p?.due||a?.date||currentDay(),'date')}</div><div id="plan-personal">${select('Traveler for this personal plan','personalPerson',peopleOptions(),personal?p?.payer||me():me())}</div><fieldset id="plan-shared">${select('Who pays upfront?','payer',peopleOptions(),p?.payer||t.defaultPayer)}${chips(p?.participants||a?.participants)}</fieldset>${select('Shared itinerary activity','activityId',[['','No linked activity'],...t.activities.map(x=>[x.id,x.title])],p?.activityId||activityId||'')}${input('Who / which provider is paid?','provider',p?.provider||'','text','maxlength="160" placeholder="Hotel, restaurant, ticket provider…"')}${p?`<label class="check-chip"><input type="checkbox" name="cancelled" ${p.cancelled?'checked':''}>Cancel the unspent plan</label>`:''}<p class="small-muted">A personal plan belongs to one traveler. A joint plan estimates each selected friend’s equal share. Neither creates debt until an actual expense is recorded.</p>`,'Save planned cost',async fd=>{const obj=Object.fromEntries(fd),personal=obj.scope==='personal',participants=personal?[obj.personalPerson]:fd.getAll('participants');if(!participants.length)throw Error('Choose at least one traveler.');await mutate(next=>{const item={...obj,payer:personal?obj.personalPerson:obj.payer,id:p?.id||uid(),title:obj.title.trim(),amount:minor(obj.amount,t.currency),participants,cancelled:fd.has('cancelled')};next.plans=p?next.plans.map(x=>x.id===p.id?item:x):[...next.plans,item];});toast('Payment plan saved in '+(personal?'the personal space.':'the joint trip.'));});const toggle=()=>{const personal=$('#f-scope').value==='personal';$('#plan-personal').classList.toggle('hidden',!personal);$('#plan-shared').classList.toggle('hidden',personal);$('#plan-shared').disabled=personal;};$('#f-scope').addEventListener('change',toggle);toggle();}

function expenseDialog({id,activityId='',planId='',refundOf=''}={}){
  const t=trip(),e=t.expenses.find(x=>x.id===id),original=t.expenses.find(x=>x.id===refundOf),p=t.plans.find(x=>x.id===(e?.planId||planId||original?.planId)),a=t.activities.find(x=>x.id===(e?.activityId||activityId||p?.activityId||original?.activityId));
  const selected=e?Object.keys(e.shares):original?Object.keys(original.shares):p?.participants||a?.participants||t.people.map(x=>x.id),currency=e?.currency||original?.currency||t.currency;
  const amount=e?major(e.amount,currency):p&&!original?major(planProgress(t,p).remaining,t.currency):'';
  const payer=e?Object.keys(e.payers)[0]:original?Object.keys(original.payers)[0]:p?.payer||t.defaultPayer;
  const single=isPersonalExpense;
  const personal=e||original?single(e||original):p?planScope(p)==='personal':space()!=='group',personalPerson=single(e||original)?Object.keys((e||original).shares)[0]:p&&planScope(p)==='personal'?p.payer:me();
  const mode=e?'exact':'equal';
  modal(original?'Record a refund':e?'Edit expense':'Add an expense',original?'Record who received it and whose costs are reduced.':'Choose personal or shared, then record the payment.',`${select('Expense type','scope',[['personal','Personal — no split'],['shared','Shared with friends']],personal?'personal':'shared')}<p class="small-muted expense-scope-help" id="scope-help"></p>${input('What was it for?','title',e?.title|| (original?'Refund: '+original.title:p?.title||a?.title||''),'text','required maxlength="160" placeholder="Dinner, train tickets, accommodation…"')}<div class="form-grid">${input('Total amount','amount',amount,'number','required min="0.0001" step="any" inputmode="decimal"')}${select('Currency','currency',currencies,currency)}${input('Payment date','date',e?.date||currentDay(),'date','required')}${select('Category','category',['Food','Stay','Transport','Explore','Other'],e?.category||a?.category||'Other')}</div><div id="personal-controls">${select(original?'Who received their personal refund?':'Who paid for their own expense?','personalPerson',peopleOptions(),personalPerson)}</div><fieldset id="shared-controls">${select(original?'Who received the refund?':'Who paid upfront?','payer',peopleOptions(),payer)}${chips(selected)}${select('How should it be split?','mode',[['equal','Equally'],['exact','Exact amounts'],['percentage','Percentages']],mode)}<div id="split-inputs"></div></fieldset><div id="rate-field" class="field ${currency===t.currency?'hidden':''}"><label for="f-rate">1 original currency unit = how many ${t.currency}?</label><input id="f-rate" name="rate" type="number" step="any" min="0.00000001" value="${e?.rate||original?.rate||1}"><small>Enter the rate manually. This expense keeps its own rate.</small></div>${select('Link to shared itinerary activity','activityId',[['','No linked activity'],...t.activities.map(x=>[x.id,x.title])],e?.activityId||a?.id||'')}<details class="advanced" ${e&&Object.keys(e.payers).length>1?'open':''}><summary>More options & notes</summary><fieldset id="multiple-controls"><label class="check-chip"><input type="checkbox" name="multiple" ${e&&Object.keys(e.payers).length>1?'checked':''}>More than one person paid upfront</label><div id="payer-inputs" class="hidden" style="margin:15px 0"></div></fieldset>${select('Link to planned cost','planId',[['','No planned cost'],...t.plans.map(x=>[x.id,x.title])],e?.planId||p?.id||'')}${textarea('Notes / receipt link','note',e?.note||'')}</details><div class="preview" id="expense-preview">Enter the amount to preview everyone’s share.</div>`,'Save '+(original?'refund':'expense'),async(fd)=>{
    const obj=Object.fromEntries(fd),participants=fd.getAll('participants'),values=Object.fromEntries(participants.map(id=>[id,fd.get('share-'+id)||0]));let payers;
    if(fd.has('multiple'))payers=Object.fromEntries(t.people.map(p=>[p.id,minor(fd.get('payer-'+p.id)||0,obj.currency)]).filter(([,v])=>v>0));
    if(obj.planId){const linkedPlan=t.plans.find(x=>x.id===obj.planId);if(linkedPlan.activityId&&obj.activityId&&linkedPlan.activityId!==obj.activityId)throw Error('Choose the activity that matches this planned cost.');obj.activityId=obj.activityId||linkedPlan.activityId||'';}
    if(obj.scope==='personal'&&obj.planId){const plan=t.plans.find(x=>x.id===obj.planId);if(planScope(plan)!=='personal'||plan.participants[0]!==obj.personalPerson)obj.planId='';}
    const item=expenseFrom({...obj,id:e?.id,participants,values,payers,kind:original?'refund':e?.kind||'expense',refundOf:original?.id||e?.refundOf||''},t);
    await mutate(next=>{next.expenses=e?next.expenses.map(x=>x.id===e.id?item:x):[...next.expenses,item];});toast(original?'Refund recorded. Balances updated.':obj.scope==='personal'?'Personal expense saved. No shared debt added.':'Shared expense saved. Balances updated.');
  });
  let savedValues=e?Object.fromEntries(Object.entries(e.shares).map(([id,v])=>[id,major(v,currency)])):{};
  function updateInputs(){const selected=$$('input[name="participants"]:checked',$('#modal')).map(x=>x.value),mode=$('#f-mode').value;$('#split-inputs').innerHTML=mode==='equal'?'':selected.map(id=>`<div class="split-row"><label for="share-${id}">${esc(name(id))} ${mode==='percentage'?'(%)':''}</label><input id="share-${id}" name="share-${id}" type="number" min="0" step="any" value="${esc(savedValues[id]??(mode==='percentage'?100/selected.length:''))}" placeholder="0"></div>`).join('');}
  $('#payer-inputs').innerHTML=t.people.map(p=>`<div class="split-row"><label for="payer-${p.id}">${esc(p.name)} paid</label><input id="payer-${p.id}" name="payer-${p.id}" type="number" min="0" step="any" value="${e?major(e.payers[p.id]||0,currency):p.id===payer?amount||'':''}" placeholder="0"></div>`).join('');
  function preview(){const personal=$('#f-scope').value==='personal';for(const id of ['shared-controls','multiple-controls']){$('#'+id).disabled=personal;$('#'+id).classList.toggle('hidden',personal);}$('#personal-controls').classList.toggle('hidden',!personal);$('#scope-help').textContent=personal?'Only this traveler pays this cost. It counts toward trip spending and is visible to the trip group.':'Choose who paid first and who shares the cost.';try{const fd=new FormData($('#dialog-form')),v=Object.fromEntries(fd),participants=fd.getAll('participants'),values=Object.fromEntries(participants.map(id=>[id,fd.get('share-'+id)||0]));$('#rate-field').classList.toggle('hidden',v.currency===t.currency);$('#payer-inputs').classList.toggle('hidden',!fd.has('multiple'));if(personal){$('#expense-preview').textContent=`${name(v.personalPerson)}: ${money(minor(v.amount,v.currency),v.currency)} · No split or debt between friends.`;return;}const shares=split(minor(v.amount,v.currency),participants,v.mode,values,v.currency);$('#expense-preview').textContent=(original?'Refund reduces: ':'Shares: ')+Object.entries(shares).map(([id,n])=>name(id)+' '+money(n,v.currency)).join(' · ');}catch(err){$('#expense-preview').textContent=err.message;}}
  updateInputs();preview();$('#dialog-form').addEventListener('change',ev=>{if(ev.target.name==='mode'||ev.target.name==='participants'){savedValues={};updateInputs();}preview();});$('#dialog-form').addEventListener('input',preview);
}
function expenseDetail(id){const t=trip(),e=t.expenses.find(x=>x.id===id);if(!e)return;modal(esc(e.title),date(e.date)+' · '+e.category+ (e.kind==='refund'?' · Refund':''),`<div class="balance-summary"><div><small>Total ${e.kind==='refund'?'refund':'expense'}</small><strong>${fmt(e.baseAmount)}</strong>${e.currency!==t.currency?`<p class="small-muted">${money(e.amount,e.currency)} · rate ${e.rate}</p>`:''}</div>${icon('money')}</div><h3>${e.kind==='refund'?'Refund received by':'Paid upfront by'}</h3>${Object.entries(e.payers).map(([id,v])=>`<div class="expense-detail"><span>${esc(name(id))}</span><strong>${money(v,e.currency)}</strong></div>`).join('')}<h3 style="margin-top:20px">${e.kind==='refund'?'Whose costs are reduced':isPersonalExpense(e)?'Personal expense — no split':'Everyone’s share'}</h3>${Object.entries(e.shares).map(([id,v])=>`<div class="expense-detail"><span>${esc(name(id))}</span><strong>${money(v,e.currency)}</strong></div>`).join('')}${e.note?`<p class="small-muted" style="margin-top:17px;white-space:pre-wrap">${esc(e.note)}</p>`:''}<div class="actions-stack">${button(icon('edit')+' Edit expense','expense','secondary',`data-id="${id}"`)}${e.kind==='expense'?button('Record a refund','refund','secondary',`data-id="${id}"`):''}${button('Delete mistaken entry','delete-expense','ghost',`data-id="${id}"`)}</div><p class="small-muted" style="margin-top:15px">If money was returned, record a refund. Delete only a mistaken entry; previous repayments remain recorded.</p>`,null);}
function repaymentDialog({from,to,amount}={}){const t=trip();if(t.people.length<2){toast('Add a friend before recording a repayment.');return;}modal('Record a repayment','Send the money outside the app, then record it here.',`<div class="form-grid">${select('Who is paying?','from',peopleOptions(),from||cloud.traveler||me())}${select('Who receives it?','to',peopleOptions(),to||t.people.find(p=>p.id!==me()).id)}${input('Amount ('+t.currency+')','amount',amount?major(Number(amount),t.currency):'','number','required step="any" min="0.0001"')}${input('Date','date',currentDay(),'date','required')}</div>${input('Method / note','note','','text','maxlength="300" placeholder="Cash, bank transfer, Revolut…"')}<div class="notice">This marks the repayment as sent. The recipient confirms receipt before balances change.${!cloudTrip||cloud.linkAccess?' Anyone with trip access can record confirmation on their behalf.':''}</div>`,'Mark as sent',async fd=>{
    const obj=Object.fromEntries(fd),baseAmount=minor(obj.amount,t.currency);if(obj.from===obj.to)throw Error('Choose two different travelers.');if(!baseAmount)throw Error('Enter a positive amount.');const s={id:uid(),from:obj.from,to:obj.to,baseAmount,date:obj.date,note:obj.note,status:'pending',reversed:false};
    const pending=t.settlements.filter(x=>x.status==='pending'&&!x.reversed&&x.from===s.from&&x.to===s.to).reduce((n,x)=>n+x.baseAmount,0),bs=balances(t);const limit=Math.min(Math.max(0,-bs[s.from].net),Math.max(0,bs[s.to].net));
    if(baseAmount+pending>limit)throw Error('This exceeds the suggested outstanding transfer after pending payments. Review existing repayments before recording another.');
    if(cloudTrip){if(t.archived)throw Error('Reopen this trip first.');await cloud.addSettlement(s);}else await mutate(next=>next.settlements.push(s));toast('Repayment marked as sent. Waiting for receipt confirmation.');
  });}
function personDialog(id){const p=trip().people.find(x=>x.id===id);modal(p?'Edit traveler':'Add a friend','Add a friend to this existing trip at any time. Their personal space is created automatically; past expense shares stay unchanged.',`${input('Name','name',p?.name||'','text','required maxlength="80"')}${p?'<p class="small-muted">Renaming updates their display name while preserving their past payments.</p>':''}`,'Save traveler',async fd=>{if(cloudTrip&&!cloud.canManage)throw Error('This trip is not editable.');await mutate(next=>{const n=String(fd.get('name')).trim();if(next.people.some(x=>x.id!==p?.id&&x.name.toLowerCase()===n.toLowerCase()))throw Error('Use a different display name so the group can tell people apart.');if(p)next.people.find(x=>x.id===p.id).name=n;else next.people.push({id:uid(),name:n});});toast(p?'Traveler renamed. Past payments are preserved.':'Friend added to this trip with a personal space.');});}
function taskDialog(){modal('A little thing to remember','Give it a name and, optionally, a person.',`${input('Task','title','','text','required maxlength="160" placeholder="Book the train, pack the charger…"')}${select('Assigned to','assignee',[['','Anyone'],...peopleOptions()])}`,'Add to checklist',async fd=>{await mutate(next=>next.tasks.push({id:uid(),title:String(fd.get('title')).trim(),assignee:fd.get('assignee'),done:false}));});}
function viewPersonDialog(){modal('Open a personal space','Choose a traveler. Their costs connect to the same master itinerary.',select('Traveler','person',peopleOptions(),me()),'Open personal space',async fd=>{chooseSpace(fd.get('person'));});}
function confirmDialog(title,body,submit,fn){modal(title,'',`<p class="small-muted">${body}</p>`,submit,fn);}
function download(content,filename,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportJson(draft=false){const t=trip();if(draft){const raw=localStorage.getItem('roam-draft-'+t.id);if(!raw){toast('No unsaved cloud draft on this device.');return;}download(raw,'roam-unsaved-draft.json');}else download(JSON.stringify({app:'roam-together',version:1,exportedAt:new Date().toISOString(),trip:t},null,2),'roam-'+t.name.replace(/[^a-z0-9]/gi,'-').toLowerCase()+'.json');}
function importDialog(){modal('Bring back a trip','Import a JSON backup from Roam Together.',`<div class="field"><label for="backup-file">Trip backup (.json)</label><input id="backup-file" type="file" name="file" accept="application/json,.json" required><small>Imports create a separate trip on this device. Shared access is never imported.</small></div>`,'Import backup',async(fd)=>{const file=fd.get('file');if(!file||file.size>1200000)throw Error('Choose a valid backup smaller than 1.2 MB.');let data;try{data=JSON.parse(await file.text());}catch{throw Error('That file is not valid JSON.');}if(data.version!==1||data.app!=='roam-together')throw Error('Choose a version 1 Roam Together backup.');const t=validateTrip(data.trip);t.id=uid();t.name=t.name+' (imported)';t.sample=false;cloud.stop();cloudTrip=null;state.trips.push(t);state.selected=t.id;state.view='home';state.day='';persist();render();toast('Backup imported as a separate local trip.');});}
function shareDialog(){if(cloud.config&&!cloud.auth){toast(cloudStatus.includes('unavailable')?'Live sharing could not connect. Your on-device trips still work.':'Connecting to live sharing. Please try again in a moment.');return;}const url=location.origin+location.pathname+'?trip='+encodeURIComponent(trip().id);if(cloudTrip){modal('Share your trip','Anyone with the link can view and edit, without signing in.',cloud.linkAccess?`${input('Trip link','link',url,'text','readonly')}<p class="small-muted">Share this link with your travel group. Changes sync live for everyone.</p>${button('Copy trip link','copy-invite','secondary')}`:`<p class="small-muted">Enable link sharing once for this older trip. Everyone with its existing link will then get access immediately.</p>${cloud.role==='owner'?button('Enable link sharing','enable-link','secondary'):'The trip owner needs to enable this once.'}`,null);return;}modal('Save & share your trip','Get a live link that friends can open immediately.',cloud.auth?`<div class="notice green">Cloud saving is ready.${cloud.user?' Signed in as '+esc(cloud.user.email)+'.':''}</div><p class="small-muted">The creator signs in once to save this trip. Friends with its link can view and edit without signing in or asking for approval.</p><div class="actions-stack">${button('Save to cloud & get link','upload-cloud','secondary')}${button('Open a shared trip','open-cloud','secondary')}${!cloud.user?button('Sign in to see my trips','sign-in-trips','ghost'):''}</div>`:`<p class="small-muted">Live sharing is unavailable. Your trip is saved on this device.</p>${button('Connect public web configuration','configure-cloud','secondary')}`,null);}

function configDialog(){modal('Connect your free database','Use the public web configuration from your Firebase project.',`${textarea('Firebase configuration (JSON)','config','')}<p class="small-muted">Paste the JSON object containing apiKey, authDomain, projectId, and appId. Never paste a service account key. The rules in firestore.rules must be deployed first. This connects only this browser; add the same public configuration to firebase-config.js before publishing for everyone.</p>`,'Connect Firebase',async fd=>{let c;try{c=JSON.parse(fd.get('config'));}catch{throw Error('Paste valid JSON with quoted property names.');}if(c.private_key||c.type==='service_account')throw Error('This is a private service account. Use the public Firebase web app configuration instead.');await cloud.init(c);sessionStorage.setItem('roam-firebase-config',JSON.stringify(c));toast('Firebase connected. Open Invite friends to sign in and share.');});}
async function openCloudDialog(id=''){let shared=[];try{if(cloud.user)shared=await cloud.list();}catch{}modal('Join a shared adventure','Open the trip link, or paste its trip ID here.',`${shared.length?select('Your shared trips','sharedTrip',[['','Choose a saved shared trip'],...shared.map(t=>[t.tripId,t.name])],id):''}${input('Trip ID or invite link','id',id,'text','required placeholder="Paste the invitation here"')}${!cloud.user?button('Sign in to see my trips','sign-in-trips','secondary'):''}<p class="small-muted">A trip link opens immediately. Guests do not need to sign in or request approval. Sign-in is only needed to find your saved trips or open an older restricted trip.</p>`,'Open shared trip',async fd=>{const id=parseTripId(fd.get('id'));if(!cloud.auth)throw Error('Connect the trip owner’s Firebase web configuration first.');await cloud.open(id);state.view='home';state.day='';history.replaceState(null,'',location.pathname+'?trip='+encodeURIComponent(id));render();toast('Shared trip opened.');});const saved=$('#f-sharedTrip');if(saved)saved.addEventListener('change',()=>{$('#f-id').value=saved.value;});}
const parseTripId=value=>{const v=String(value).trim();if(/^https?:/.test(v)){try{return new URL(v).searchParams.get('trip')||v;}catch{}}return v;};
async function copyInvite(){if(!cloudTrip)return shareDialog();const url=location.origin+location.pathname+'?trip='+encodeURIComponent(trip().id);try{await navigator.clipboard.writeText(url);toast('Trip link copied. Anyone with it can open and edit immediately.');}catch{modal('Your trip invitation','Share this link with your friends.',input('Invitation link','link',url,'text','readonly'),null);}}

document.addEventListener('click',async ev=>{
  const target=ev.target.closest('[data-action]');if(!target)return;ev.preventDefault();const {action,id,activity,plan:planId,from,to,amount}=target.dataset;
  try{
    if(action.startsWith('go-')){state.view=action.slice(3);search='';persist();render();window.scrollTo({top:0,behavior:'smooth'});return;}
    if(action==='close'){$('#modal').close();editRevision=null;return;}
    if(action==='day'){state.day=target.dataset.day;persist();render();return;}
    if(action==='money-tab'){state.moneyTab=target.dataset.tab;persist();render();return;}
    const editing=['budget','expense','activity','planned','repayment','person','task','refund','delete-task','delete-expense','delete-activity'];
    if(editing.includes(action)&&(!canEdit()||trip().archived))throw Error(trip().archived?'Reopen the trip before making changes.':'You have view-only access.');
    if(action==='new-trip')settingsDialog(true);
    else if(action==='budget'){if(cloudTrip&&!cloud.canManage)throw Error('This trip is not editable.');budgetDialog();}
    else if(action==='settings'){if(cloudTrip&&!cloud.canManage)throw Error('This trip is not editable.');settingsDialog(false);}
    else if(action==='activity')activityDialog(id);
    else if(action==='activity-detail')activityDetail(id);
    else if(action==='planned')plannedDialog(id,activity);
    else if(action==='expense')expenseDialog({id,activityId:activity,planId});
    else if(action==='expense-detail')expenseDetail(id);
    else if(action==='refund')expenseDialog({refundOf:id});
    else if(action==='repayment')repaymentDialog({from,to,amount});
    else if(action==='person')personDialog(id);
    else if(action==='task')taskDialog();
    else if(action==='view-person')viewPersonDialog();
    else if(action==='open-personal')chooseSpace(target.dataset.person);
    else if(action==='open-group')chooseSpace('group');
    else if(action==='delete-task')await mutate(next=>{next.tasks=next.tasks.filter(x=>x.id!==id);},{revision:cloudTrip?cloud.revision:null});
    else if(action==='delete-expense')confirmDialog('Remove a mistaken entry?','This removes this expense from balances. Actual refunds should be recorded as refunds. Existing repayment records will remain. Export a backup first if you need a permanent copy.','Remove entry',async()=>{await mutate(next=>{if(next.expenses.some(e=>e.refundOf===id))throw Error('Remove linked mistaken refunds first, or correct this purchase instead.');next.expenses=next.expenses.filter(x=>x.id!==id);});toast('Entry removed. Balances recalculated.');});
    else if(action==='delete-activity')confirmDialog('Remove this stop?','Payments and planned costs must be unlinked first, so your records stay complete.','Remove activity',async()=>{await mutate(next=>{if(next.plans.some(p=>p.activityId===id)||next.expenses.some(e=>e.activityId===id))throw Error('Unlink this activity from its planned costs and expenses first.');next.activities=next.activities.filter(a=>a.id!==id);});});
    else if(action==='confirm-settlement'){const s=trip().settlements.find(s=>s.id===id);confirmDialog('Has the money arrived?',`${esc(name(s.to))} ${name(s.to)==='You'?'confirm':'confirms'} receiving ${fmt(s.baseAmount)} from ${esc(name(s.from))}. This will update both balances.`,'Confirm received',async()=>{if(trip().archived||!canEdit())throw Error('This trip is not editable.');if(cloudTrip)await cloud.confirmSettlement(s);else await mutate(next=>{const row=next.settlements.find(x=>x.id===id);row.status='confirmed';row.confirmedAt=new Date().toISOString();});toast('Receipt confirmed. Balances updated.');});}
    else if(action==='reverse-settlement'){const s=trip().settlements.find(s=>s.id===id);confirmDialog('Reverse this receipt record?','The original repayment remains in history and will stop affecting balances. This does not send or return real money.','Reverse record',async()=>{if(trip().archived||!canEdit())throw Error('This trip is not editable.');if(cloudTrip)await cloud.reverseSettlement(s);else await mutate(next=>{next.settlements.find(x=>x.id===id).reversed=true;});});}
    else if(action==='export-csv'){download(csv(trip()),'roam-expenses.csv','text/csv;charset=utf-8');toast('Expense CSV downloaded.');}
    else if(action==='export-json')exportJson();
    else if(action==='export-draft')exportJson(true);
    else if(action==='import')importDialog();
    else if(action==='print'){printTrip();}
    else if(action==='archive'){if(cloudTrip&&cloud.role!=='owner')throw Error('Only the owner can archive or reopen the trip.');await mutate(next=>{next.archived=!next.archived;},{allowArchive:true,revision:cloudTrip?cloud.revision:null});toast(trip().archived?'Trip archived.':'Trip reopened.');}
    else if(action==='reset-sample')confirmDialog('Reset the sample adventure?','This replaces the fictional sample trip with fresh example data. Your other trips are preserved.','Reset sample',async()=>{const sample=sampleTrip();state.trips=state.trips.map(t=>t.id===trip().id?sample:t);state.selected=sample.id;undo=null;persist();render();});
    else if(action==='undo'){if(undo&&!cloudTrip){const old=undo;undo=structuredClone(trip());state.trips=state.trips.map(t=>t.id===old.id?old:t);persist();render();toast('Last change undone.');}}
    else if(action==='share')shareDialog();
    else if(action==='sign-in-trips'){if(!cloud.auth)throw Error('Live sharing is still connecting. Please try again in a moment.');if(!cloud.user)await cloud.signIn();await openCloudDialog();}
    else if(action==='configure-cloud')configDialog();
    else if(action==='open-cloud')openCloudDialog();
    else if(action==='copy-invite')await copyInvite();
    else if(action==='upload-cloud'){if(!cloud.user)await cloud.signIn();const sharedId=await cloud.create(trip());$('#modal').close();state.view='trip';history.replaceState(null,'',location.pathname+'?trip='+encodeURIComponent(sharedId));render();shareDialog();toast('Saved to cloud. Your trip link is ready.');}
    else if(action==='enable-link'){await cloud.enableLinkSharing();shareDialog();toast('Link sharing enabled. Friends can open the link immediately.');}
    else if(action==='signout'){await cloud.signOut();cloudTrip=null;history.replaceState(null,'',location.pathname);render();toast('Signed out. Shared trip data is no longer displayed.');}
  }catch(e){error(e);}
});
document.addEventListener('change',async ev=>{try{
  if(ev.target.matches('[data-task]')){const checked=ev.target.checked,id=ev.target.dataset.task;await mutate(next=>{next.tasks.find(t=>t.id===id).done=checked;},{revision:cloudTrip?cloud.revision:null});}
  if(['trip-select','trip-page-select'].includes(ev.target.id)&&ev.target.value!=='cloud'){cloud.stop();cloud.trip=null;cloud.meta=null;cloudTrip=null;state.selected=ev.target.value;state.day='';history.replaceState(null,'',location.pathname);persist();render();}
  if(ev.target.id==='person-select'||ev.target.id==='workspace-select')chooseSpace(ev.target.value);
}catch(e){render();error(e);}});
document.addEventListener('input',ev=>{if(ev.target.id==='expense-search'){search=ev.target.value;$('#expense-table').innerHTML=expenseRows();}});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[role="button"][data-action]')){ev.preventDefault();ev.target.click();}});
$('#modal').addEventListener('close',()=>{editRevision=null;});
window.addEventListener('storage',ev=>{if(ev.key==='roam-state-v1'&&!cloudTrip){try{const next=JSON.parse(ev.newValue);next.trips.forEach(validateTrip);state=next;render();toast('Trip updated in another tab.');}catch{}}});
window.addEventListener('online',()=>{render();toast('Back online. Review any unsaved drafts before sharing.');});window.addEventListener('offline',render);
function printTrip(){const t=trip();let section=document.createElement('section');section.className='print-all';section.style.display='none';section.innerHTML=`<h1>${esc(t.name)}</h1><p>${esc(t.destination)} · ${date(t.start)}–${date(t.end)}</p><p>Budget ${fmt(t.budget)} · Spent ${fmt(totals(t).spent)} · Forecast ${fmt(totals(t).forecast)}</p>${dates(t.start,t.end).map(d=>`<h2 style="margin:22px 0 10px">${date(d,{weekday:'long',day:'numeric',month:'long'})}</h2>${t.activities.filter(a=>a.date===d).sort((a,b)=>a.time.localeCompare(b.time)).map(a=>`<div class="card"><h3>${esc(a.time)}–${esc(a.endTime)} · ${esc(a.title)}</h3><p>${esc(a.address)}</p><p>${esc(a.meeting||'')}</p><p>${esc(a.notes)}</p></div>`).join('')}`).join('')}<h2>Who pays whom</h2>${transfers(t).map(s=>`<p>${esc(name(s.from))} → ${esc(name(s.to))}: ${fmt(s.amount)}</p>`).join('')||'<p>All settled.</p>'}`;document.body.append(section);const style=document.createElement('style');style.textContent='@media print{#app{display:none!important}.print-all{display:block!important}}';document.head.append(style);window.print();section.remove();style.remove();}
render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
(async()=>{try{let config;try{config=JSON.parse(sessionStorage.getItem('roam-firebase-config'));}catch{}const ready=await cloud.init(config||undefined);const invite=new URL(location.href).searchParams.get('trip');if(invite){if(ready){try{await cloud.open(invite);}catch(e){await openCloudDialog(invite);toast(e.message);}}else{shareDialog();}}}catch(e){cloudStatus='Live sharing unavailable';render();toast('Live sharing is unavailable: '+e.message);}finally{openingShared=false;render();}})();
